import ctypes as C, re, xml.etree.ElementTree as ET, pathlib
c=C.CDLL('libcairo.so.2')
def bind(name,types,ret=None):
    f=getattr(c,'cairo_'+name);f.argtypes=types;f.restype=ret;return f
P=C.c_void_p; D=C.c_double; I=C.c_int
surface=bind('image_surface_create',[I,I,I],P);create=bind('create',[P],P)
for name,types in [('set_source_rgb',[P,D,D,D]),('paint',[P]),('save',[P]),('restore',[P]),('translate',[P,D,D]),('scale',[P,D,D]),('move_to',[P,D,D]),('line_to',[P,D,D]),('curve_to',[P,D,D,D,D,D,D]),('close_path',[P]),('fill',[P]),('rectangle',[P,D,D,D,D]),('set_font_size',[P,D]),('show_text',[P,C.c_char_p]),('select_font_face',[P,C.c_char_p,I,I]),('set_antialias',[P,I])]: bind(name,types)
write=bind('surface_write_to_png',[P,C.c_char_p],I)
def color(ctx,h): c.cairo_set_source_rgb(ctx,*[int(h[i:i+2],16)/255 for i in (1,3,5)])
def path(ctx,d):
    tokens=re.findall(r'[MLHVQCZmlhvqcz]|-?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?',d);i=0;x=y=0;start=(0,0)
    while i<len(tokens):
        cmd=tokens[i];i+=1;n={'M':2,'L':2,'H':1,'V':1,'Q':4,'C':6,'Z':0}[cmd];v=list(map(float,tokens[i:i+n]));i+=n
        if cmd=='M': x,y=v;start=(x,y);c.cairo_move_to(ctx,x,y)
        elif cmd=='L': x,y=v;c.cairo_line_to(ctx,x,y)
        elif cmd=='H': x=v[0];c.cairo_line_to(ctx,x,y)
        elif cmd=='V': y=v[0];c.cairo_line_to(ctx,x,y)
        elif cmd=='Q':
            a,b,xx,yy=v;c.cairo_curve_to(ctx,x+2*(a-x)/3,y+2*(b-y)/3,xx+2*(a-xx)/3,yy+2*(b-yy)/3,xx,yy);x,y=xx,yy
        elif cmd=='C': c.cairo_curve_to(ctx,*v);x,y=v[-2:]
        elif cmd=='Z': c.cairo_close_path(ctx);x,y=start

def draw(ctx,filename,x,y,w,h=None,override=None):
    root=ET.parse(filename).getroot();vb=list(map(float,root.get('viewBox').split()));h=h or w*vb[3]/vb[2]
    c.cairo_save(ctx);c.cairo_translate(ctx,x,y);c.cairo_scale(ctx,w/vb[2],h/vb[3]);
    def walk(el,fill):
        c.cairo_save(ctx);fill=override or el.get('fill',fill); color(ctx,fill)
        for name,args in re.findall(r'(translate|scale)\\((["'^)]+)'"\\)',el.get('transform','')):
            nums=[float(a) for a in re.split('[ ,]+',args)];
            if name=='translate': c.cairo_translate(ctx,nums[0],nums[1] if len(nums)>1 else 0)
            else: c.cairo_scale(ctx,nums[0],nums[1] if len(nums)>1 else nums[0])
        if el.tag.endswith('path'):path(ctx,el.get('d'));c.cairo_fill(ctx)
        for child in el:walk(child,fill)
        c.cairo_restore(ctx)
    walk(root,'#000000');c.cairo_restore(ctx)
def rect(ctx,x,y,w,h,col):color(ctx,col);c.cairo_rectangle(ctx,x,y,w,h);c.cairo_fill(ctx)
def label(ctx,x,y,s,col='#7c8178'):
    color(ctx,col);c.cairo_select_font_face(ctx,b'sans',0,0);c.cairo_set_font_size(ctx,13);c.cairo_move_to(ctx,x,y);c.cairo_show_text(ctx,s.encode())
if __name__=='__main__':
    work=pathlib.Path('/tmp/fernway-logo-work');s=surface(0,1000,800);ctx=create(s);rect(ctx,0,0,1000,800,'#f4f0e5')
    for k,name in enumerate(['display','bold','serif']):
        draw(ctx,str(work/(name+'.svg')),90,40+k*200,800)
        label(ctx,90,210+k*200,name)
    draw(ctx,str(work/'mark.svg'),100,670,96)
    draw(ctx,str(work/'mark.svg'),250,700,32)
    draw(ctx,str(work/'mark.svg'),320,708,16)
    write(s,str(work/'compare.png').encode())
